import base64, json, mimetypes, re
from pathlib import Path
from html import escape as esc
STYLES={"redwhite":("红白双喜","喜帖轻启，良缘成章"),"floral":("花鸟雅韵","花开有时，佳期有约"),"gold":("酒红鎏金","以爱为名，共赴良辰")}
def render_preview_app(pages: dict[str, str], output: Path, data: dict) -> str:
    embedded = {}
    for style, page in pages.items():
        def inline(match):
            local = output / match.group(1)
            mime = mimetypes.guess_type(local.name)[0] or "application/octet-stream"
            return 'src="data:' + mime + ';base64,' + base64.b64encode(local.read_bytes()).decode("ascii") + '"'
        embedded[style] = re.sub(r'src="(media/[^"<>]+)"', inline, page)
    encoded = json.dumps(embedded, ensure_ascii=False).replace("<", "\\u003c")
    tabs = "".join(f'<button data-style="{style}">{esc(STYLES[style][0])}</button>' for style in pages)
    first = next(iter(pages))
    hint = "演示资料仅供预览，请核对并补全真实信息。" if data.get("demo") else "页面使用当前提供的照片与信息，请核对姓名、时间和地点。"
    initial = json.dumps({'effects': data['effects'], 'particles': data['particles'], 'photo_transition': data['photo_transition']})
    hint += "配乐已接入，可静音浏览；切换风格会停止上一款音乐。" if any('id="musicAudio"' in page for page in pages.values()) else "当前关闭 BGM，可静音查看动效。"
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>动态婚礼电子请柬 · 特效与配乐预览</title><style>*{{box-sizing:border-box}}body{{margin:0;background:radial-gradient(ellipse at 50% 0,#fff6e8,#ede0d3);color:#681d29;font-family:"Noto Serif SC","Songti SC",serif}}main{{max-width:980px;margin:auto;padding:28px 16px 45px;text-align:center}}.eyebrow{{font:11px system-ui,sans-serif;letter-spacing:.32em}}h1{{font-weight:500;font-size:clamp(25px,4vw,38px);margin:15px 0}}p{{line-height:1.8;margin:12px auto;font-size:14px}}.tabs{{display:flex;justify-content:center;gap:8px;flex-wrap:wrap;margin:24px auto}}.tabs button{{background:#fff9ef;border:1px solid #aa7a7d;color:#6e1a25;padding:12px 17px;cursor:pointer;font:inherit;font-size:14px}}.tabs button.active{{background:#7f1521;color:#fff3d7}}.phone{{width:min(100%,420px);height:min(76svh,820px);min-height:360px;margin:auto;padding:5px;background:#23161b;border:6px solid #23161b;border-radius:28px;box-shadow:0 25px 70px #3d1e3140}}.phone iframe{{border:0;width:100%;height:100%;display:block;border-radius:17px;background:#fff}}.controls{{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;align-items:center;margin:16px auto;font:13px/1.8 system-ui,sans-serif}}.controls select{{font:inherit;padding:6px;background:#fff9ef;border:1px solid #aa7a7d;color:#6e1a25}}.hint{{color:#8b6266;font-size:12px;max-width:500px}}@media(max-width:420px){{main{{padding:22px 10px}}.phone{{height:72svh;min-height:340px;border:3px solid #23161b;padding:3px}}}}</style></head><body><main><div class="eyebrow">A LETTER OF LOVE</div><h1>把喜事，写进一封会动的请帖</h1><p>切换风格，点击开帖入口试听配乐，调节动效强度。</p><div class="tabs">{tabs}</div><div class="controls"><label>动效强度 <select id="effectSelect"><option value="off">静态</option><option value="subtle">轻柔</option><option value="normal" selected>标准</option><option value="festive">喜庆</option></select></label><label><input id="particleToggle" type="checkbox" checked> 氛围粒子</label><label><input id="photoToggle" type="checkbox" checked> 照片入场</label></div><div class="phone"><iframe id="frame" title="婚礼电子请柬预览" allow="autoplay"></iframe></div><p class="hint">{esc(hint)}</p></main><script>const initial={initial};const pages={encoded};const frame=document.getElementById('frame');const effects=document.getElementById('effectSelect'),particles=document.getElementById('particleToggle'),photo=document.getElementById('photoToggle');effects.value=initial.effects;particles.checked=initial.particles;photo.checked=initial.photo_transition;function tune(){{frame.contentWindow.postMessage({{type:'invitation-preview',effects:effects.value,particles:particles.checked,photo_transition:photo.checked}},'*')}}frame.addEventListener('load',tune);[effects,particles,photo].forEach(el=>el.addEventListener('change',tune));function show(k){{frame.srcdoc=pages[k];document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.style===k));document.querySelectorAll('.tabs button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.style===k)))}}document.querySelectorAll('.tabs button').forEach(b=>b.addEventListener('click',()=>show(b.dataset.style)));show('{first}');</script></body></html>'''
